from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class ServedamfParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        amf_num = self.mo_num
        amf_ip_addr = kwargs['epc_config'][f'amf{amf_num}']['ip_addr']
        self.set_parameter('amfIPAddress', amf_ip_addr)
        if 'default' in kwargs['epc_config'][f'amf{amf_num}']:
            self.set_parameter('defaultAMF', kwargs['epc_config'][f'amf{amf_num}']['default'])
